-- ============================================================
-- Osman Bey mod - unique units and buildings
-- Every unique copies the full row of the unit or building it
-- replaces, so all Brave New World columns are filled correctly.
-- Generated by tools/build_mod.py.
-- ============================================================

-- ------------------------------------------------------------
-- Units
-- ------------------------------------------------------------
CREATE TABLE OB_UnitMap (NewType TEXT, BaseType TEXT, Tag TEXT);
INSERT INTO OB_UnitMap (NewType, BaseType, Tag) VALUES
	('UNIT_OB_AKINCI',   'UNIT_KNIGHT',            'AKINCI'),
	('UNIT_OB_YENICERI', 'UNIT_OTTOMAN_JANISSARY', 'YENICERI'),
	('UNIT_OB_SAHI',     'UNIT_TREBUCHET',         'SAHI');

CREATE TABLE OB_TmpUnits AS SELECT * FROM Units WHERE 0;
INSERT INTO OB_TmpUnits SELECT u.* FROM Units u INNER JOIN OB_UnitMap m ON u.Type = m.BaseType;
UPDATE OB_TmpUnits SET
	ID          = NULL,
	Description = 'TXT_KEY_UNIT_OB_'      || (SELECT Tag FROM OB_UnitMap WHERE BaseType = OB_TmpUnits.Type),
	Civilopedia = 'TXT_KEY_CIV5_UNIT_OB_' || (SELECT Tag FROM OB_UnitMap WHERE BaseType = OB_TmpUnits.Type) || '_TEXT',
	Strategy    = 'TXT_KEY_UNIT_OB_'      || (SELECT Tag FROM OB_UnitMap WHERE BaseType = OB_TmpUnits.Type) || '_STRATEGY',
	Help        = 'TXT_KEY_UNIT_HELP_OB_' || (SELECT Tag FROM OB_UnitMap WHERE BaseType = OB_TmpUnits.Type),
	Type        = (SELECT NewType FROM OB_UnitMap WHERE BaseType = OB_TmpUnits.Type);
INSERT INTO Units SELECT * FROM OB_TmpUnits;
DROP TABLE OB_TmpUnits;

